/**
 * Credential Verification Script
 * Tests connectivity to services using credentials from .env.test
 * Designed to work with both real and CANARY test credentials
 */

const fs = require('fs');
const path = require('path');
const https = require('https');

// Load .env file if it exists
const envPath = path.join(__dirname, '.env.test');
const envVars = {};

if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      envVars[key.trim()] = value.trim();
    }
  }
  console.log('[INFO] Loaded credentials from .env.test');
} else {
  console.log('[INFO] No .env.test file found. Using environment variables only.');
}

// Helper function to check environment variable
function hasEnvVar(name) {
  const value = envVars[name] || process.env[name];
  return { present: !!value, value };
}

// Test PostgreSQL connection (using canary credentials)
async function testPostgreSQL() {
  console.log('\n=== PostgreSQL Connection Test ===');
  const { present, value } = hasEnvVar('DATABASE_URL');

  if (!present) {
    console.log('[SKIP] DATABASE_URL not set');
    return { passed: false, reason: 'Not configured' };
  }

  console.log(`[TEST] DATABASE_URL: ${value.substring(0, 20)}***`);

  // Extract host from URL for connection test
  try {
    const url = new URL(value);
    const host = url.hostname;
    const port = url.port || 5432;

    console.log(`[TEST] Target host: ${host}:${port}`);
    console.log('[INFO] Testing PostgreSQL connectivity...');

    // Note: Without pg library, we can only validate URL format
    console.log('[INFO] URL format validation: PASSED');
    console.log('[WARNING] Full PostgreSQL connectivity test requires pg library');

    // Check if it's a canary URL (expected to fail or timeout)
    if (value.includes('CANARY')) {
      console.log('[INFO] Detected CANARY credential - expected to fail');
    }

    return { passed: true, reason: 'URL format valid' };
  } catch (err) {
    console.log(`[FAIL] Invalid DATABASE_URL format: ${err.message}`);
    return { passed: false, reason: 'Invalid URL format' };
  }
}

