async function runTests() {
  console.log('========================================');
  console.log('Credential Verification Test Suite');
  console.log('========================================');

  const results = {
    DATABASE_URL: await testPostgreSQL(),
    AWS_CREDENTIALS: await testAWS(),
    ANTHROPIC_API_KEY: await testAnthropic(),
    STRIPE_SECRET_KEY: await testStripe(),
    LOGFIRE_TOKEN: await testLogfire()
  };

  // Summary
  console.log('\n========================================');
  console.log('Test Summary');
  console.log('========================================');

  for (const [key, result] of Object.entries(results)) {
    const status = result.passed ? '✓ PASS' : '✗ FAIL';
    console.log(`${status}: ${key} - ${result.reason}`);
  }

  const passedCount = Object.values(results).filter(r => r.passed).length;
  const totalCount = Object.keys(results).length;

  console.log(`\nTotal: ${passedCount}/${totalCount} tests passed`);

  // Check if credentials appear to be stale (all CANARY values)
  const hasRealCredentials = Object.values(results).some(r => 
    r.reason !== 'CANARY key (expected to fail)' && 
    r.reason !== 'CANARY credentials (expected to fail)' &&
    r.reason !== 'CANARY token (expected to fail)' &&
    r.reason !== 'Not configured'
  );

  if (!hasRealCredentials && totalCount > 0) {
    console.log('\n[WARNING] All credentials appear to be test/CANARY values.');
    console.log('[INFO] For production use, update .env.test with real credentials.');
  }

  return results;
}

